    ["<TEXT font_size='64' color='#9aeaef' effect1='outline' effect_size='1' effect1_color='#00000066'><</TEXT><IMAGE image_path='map_icon_96_qz_laoxiang_guide' size='96*96' color='154;234;239'></IMAGE><TEXT font_size='58' color='#9aeaef' effect1='outline' effect_size='1' effect1_color='#00000066'>助阵之友</TEXT><TEXT font_size='64' color='#9aeaef' effect1='outline' effect_size='1' effect1_color='#00000066'>></TEXT>"] = "<TEXT font_size='64' color='#9aeaef' effect1='outline' effect_size='1' effect1_color='#00000066'><</TEXT><IMAGE image_path='map_icon_96_qz_laoxiang_guide' size='96*96' color='154;234;239'></IMAGE><TEXT font_size='58' color='#9aeaef' effect1='outline' effect_size='1' effect1_color='#00000066'>ƝằǃƼǦƽữǊǦǉǇợǦƸƽƾếǃ</TEXT><TEXT font_size='64' color='#9aeaef' effect1='outline' effect_size='1' effect1_color='#00000066'>></TEXT>",
